function changed(a,b,path=''){if(JSON.stringify(a)===JSON.stringify(b))return [];if(Array.isArray(a)&&Array.isArray(b)&&[...a,...b].length&&[...a,...b].every(x=>x&&typeof x==='object'&&x.id)){const order=a.map(x=>x.id).join('|')!==b.map(x=>x.id).join('|')?[{field:path+'.order',before:a.map(x=>x.name||x.title||x.id),after:b.map(x=>x.name||x.title||x.id)}]:[];return [...order,...new Set([...a,...b].map(x=>x.id))].flatMap(x=>typeof x==='object'?[x]:changed(a.find(y=>y.id===x),b.find(y=>y.id===x),path+'.'+x));}if(!a||!b||typeof a!=='object'||typeof b!=='object'||Array.isArray(a)||Array.isArray(b))return [{field:path,before:cp(a??null),after:cp(b??null)}];return [...new Set([...Object.keys(a),...Object.keys(b)])].flatMap(k=>changed(a[k],b[k],path?path+'.'+k:k))}
function safe(x,key=''){if(/password|secret|token|document(image|pending)?|signature|stamp|ktp|imageurl|storagekey|attachment|cover|audio/i.test(key))return '[Data dilindungi]';if(/^(number|nik|accountnumber|banknumber)$/i.test(key))return '[Nomor dilindungi]';if(typeof x==='string'&&x.startsWith('data:'))return '[Berkas]';if(Array.isArray(x))return x.map(v=>safe(v));if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,safe(v,k)]));return x??null}
